head.b:skin:
/* =========================================================================
   CRYPTO ACADEMY ONLINE - STANDALONE HIGH-FIDELITY CYBERNETIC THEME
   ========================================================================= */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&amp;family=Share+Tech+Mono&amp;family=Outfit:wght@400;500;600;700;800;900&amp;display=swap');

:root {
  --bg-main: #060a12;
  --bg-card: #0b1524;
  --text-main: #e2e8f0;
  --text-muted: #94a3b8;
  --accent: #00e5ff;
  --accent-hover: #33ecff;
  --border: rgba(0, 229, 255, 0.15);
  --border-bright: rgba(0, 229, 255, 0.45);
}

/* Reset and Core Styling */
html, body {
  background-color: var(--bg-main);
  color: var(--text-main);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  scroll-behavior: smooth;
  overflow-x: hidden;
  width: 100%;
  position: relative;
}

/* Branded Loading Screen */
#ca-page-loader {
  position: fixed;
  inset: 0;
  background: #060a12;
  z-index: 999999999;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}

#ca-page-loader.ca-loader-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.ca-loader-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.1rem;
}

.ca-loader-logo {
  filter: drop-shadow(0 0 12px rgba(0, 229, 255, 0.6));
  animation: caLoaderPulse 1.6s ease-in-out infinite;
}

@keyframes caLoaderPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.65; transform: scale(0.9); }
}

.ca-loader-title {
  font-family: 'Outfit', sans-serif;
  font-weight: 800;
  font-size: 0.8rem;
  letter-spacing: 3px;
  color: var(--accent);
  text-transform: uppercase;
  text-align: center;
}

.ca-loader-bar-track {
  width: 160px;
  height: 3px;
  background: rgba(0, 229, 255, 0.15);
  border-radius: 2px;
  overflow: hidden;
}

.ca-loader-bar-fill {
  height: 100%;
  width: 40%;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  animation: caLoaderBar 1.2s ease-in-out infinite;
}

@keyframes caLoaderBar {
  0% { transform: translateX(-120%); }
  100% { transform: translateX(340%); }
}

.ca-loader-status {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.62rem;
  letter-spacing: 1px;
  color: var(--text-muted);
  text-transform: uppercase;
}

/* Glowing Glass Header Navigation */
.theme-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(6, 10, 18, 0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  padding: 1.25rem 2rem;
  transition: all 0.3s ease;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo-container {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  flex-shrink: 0;
}

.logo-icon {
  width: 28px;
  height: 28px;
  color: var(--accent);
  filter: drop-shadow(0 0 8px rgba(0, 229, 255, 0.6));
  flex-shrink: 0;
}

.logo-text-wrap {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}

.logo {
  font-family: 'Outfit', sans-serif;
  font-size: 1.25rem;
  font-weight: 900;
  color: var(--accent);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  text-shadow: 0 0 10px rgba(0, 229, 255, 0.4);
  line-height: 1.1;
  white-space: nowrap;
}

.logo-tagline {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.55rem;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 2px;
  text-transform: uppercase;
  opacity: 0.8;
  margin-top: 2px;
  text-align: left;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
}

.nav-hamburger-btn {
  display: none;
}

@media (max-width: 900px) {
  .theme-header {
    backdrop-filter: none !important;
    background: #060a12 !important;
    padding: 1rem 1.25rem !important;
  }

  .logo-container {
    position: relative;
    z-index: 100001 !important;
  }

  .logo {
    font-size: 1.05rem !important;
    letter-spacing: 1px !important;
    white-space: nowrap !important;
  }

  .logo-tagline {
    font-size: 0.5rem !important;
    letter-spacing: 1.5px !important;
  }

  @media (max-width: 480px) {
    .logo-container {
      gap: 0.5rem !important;
    }
    .logo {
      font-size: 0.9rem !important;
      letter-spacing: 0.5px !important;
    }
    .logo-tagline {
      font-size: 0.45rem !important;
      letter-spacing: 1px !important;
    }
    .logo-icon {
      width: 24px !important;
      height: 24px !important;
    }
  }

  .nav-links {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background-color: #060a12 !important;
    background: #060a12 !important;
    border-bottom: 2px solid rgba(0, 229, 255, 0.15);
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 0;
    padding: 0.5rem 1.25rem 1rem;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translateY(-8px);
    transition: opacity 0.25s ease, transform 0.25s ease, visibility 0.25s;
    z-index: 100000 !important;
  }

  body.ca-nav-open .nav-links {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateY(0);
  }

  .nav-links .nav-link {
    font-size: 0.85rem;
    padding: 0.65rem 0.5rem;
    width: 100%;
    border-bottom: 1px solid rgba(0, 229, 255, 0.08);
    color: var(--text-main);
    text-align: left;
  }

  .nav-links .btn-subscribe {
    margin-top: 0.85rem;
    width: calc(100% - 1rem);
    text-align: center;
    padding: 0.6rem;
    font-size: 0.72rem;
  }

  .nav-hamburger-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    color: var(--accent);
    cursor: pointer;
    padding: 0.4rem;
    z-index: 100001 !important;
    transition: color 0.2s, text-shadow 0.2s;
    filter: drop-shadow(0 0 4px rgba(0, 229, 255, 0.4));
  }

  .nav-hamburger-btn:hover {
    color: var(--accent-hover);
  }
}

.nav-link {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  transition: color 0.2s, text-shadow 0.2s;
}

.nav-link:hover {
  color: var(--accent);
  text-shadow: 0 0 8px rgba(0, 229, 255, 0.6);
}

.btn-subscribe {
  background: var(--accent);
  color: #060a12;
  padding: 0.5rem 1.25rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-decoration: none;
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.25);
  transition: all 0.25s ease;
}

.btn-subscribe:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 25px rgba(0, 229, 255, 0.45);
  transform: translateY(-1px);
}

/* Horizontal Market Ticker bar */
.market-ticker-wrap {
  background: #02060c;
  border-bottom: 1px solid var(--border);
  padding: 0.85rem 0;
  overflow: hidden;
  position: relative;
  z-index: 10;
}

.market-ticker-container {
  display: flex;
  width: max-content;
  gap: 1rem;
  animation: ticker-scroll 30s linear infinite;
}

.market-ticker-container:hover {
  animation-play-state: paused;
}

@keyframes ticker-scroll {
  0% {
    transform: translate3d(0, 0, 0);
  }
  100% {
    transform: translate3d(-50%, 0, 0);
  }
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.9rem;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0.4rem 1rem;
}

.ticker-logo {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.06);
}

.ticker-symbol {
  color: var(--accent);
  font-weight: bold;
  text-transform: uppercase;
  text-shadow: 0 0 6px rgba(0, 229, 255, 0.3);
}

.ticker-price {
  color: var(--text-main);
  font-weight: 500;
}

.ticker-change {
  font-size: 0.85rem;
  font-weight: 600;
}

.ticker-change.up {
  color: #10b981;
}

.ticker-change.down {
  color: #ef4444;
}

/* Hero Action Buttons styling */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.95rem 2rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-weight: 800;
  font-family: 'Outfit', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-decoration: none;
  transition: all 0.25s ease;
  cursor: pointer;
  box-sizing: border-box;
  text-align: center;
}

.btn-primary {
  background: var(--accent);
  color: #060a12;
  border: 1px solid var(--accent);
  box-shadow: 0 0 15px rgba(0, 229, 255, 0.25);
}

.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  box-shadow: 0 0 30px rgba(0, 229, 255, 0.6);
  transform: translateY(-2px);
}

.btn-secondary {
  background: rgba(6, 10, 18, 0.4);
  color: #ffffff;
  border: 1px solid rgba(0, 229, 255, 0.25);
  backdrop-filter: blur(5px);
}

.btn-secondary:hover {
  background: rgba(0, 229, 255, 0.08);
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 0 0 20px rgba(0, 229, 255, 0.25);
  transform: translateY(-2px);
}

/* Interactive Hero Section */
.hero {
  max-width: 1200px;
  margin: 0 auto;
  padding: 4.5rem 2rem;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 3.5rem;
  align-items: center;
  position: relative;
  z-index: 10;
}

@media (max-width: 900px) {
  .hero {
    grid-template-columns: 1fr;
    gap: 3rem;
    padding: 3rem 1.5rem;
  }

  .hero-title {
    font-size: 2.25rem !important;
    letter-spacing: -1px !important;
  }

  .emblem-container {
    height: 280px !important;
  }
}

.hero-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
}

.hero-eyebrow-row {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  margin-bottom: 1.25rem;
}

.eyebrow-item {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.eyebrow-item.green {
  color: #10b981;
}

.hero-title {
  font-family: 'Outfit', sans-serif;
  font-size: 3.6rem;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -1.5px;
  color: #ffffff;
  margin: 0 0 1.25rem 0;
  text-align: left;
}

.hero-title span {
  background: linear-gradient(135deg, var(--accent), #e2e8f0);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 0 25px rgba(0, 229, 255, 0.15);
}

.hero-desc {
  font-size: 0.9rem;
  line-height: 1.5;
  color: var(--text-muted);
  margin: 0 0 2rem 0;
  max-width: 500px;
  text-align: left;
}

.hero-actions {
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
}

/* Market Pulse Card */
.market-pulse-card {
  background: rgba(11, 21, 36, 0.7);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.5rem;
  position: relative;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
  width: 100%;
  box-sizing: border-box;
}

.market-pulse-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0, 229, 255, 0.3), transparent);
}

.ai-summary-header {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.ai-summary-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 10px;
  border: 1px solid rgba(16, 185, 129, 0.35);
  background: rgba(16, 185, 129, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #10b981;
}

.ai-summary-title {
  color: #ffffff;
  font-size: 1.05rem;
  font-weight: 700;
  margin: 0;
}

.ai-stat-card {
  background: rgba(6, 10, 18, 0.6);
  border: 1px solid rgba(0, 229, 255, 0.08);
  border-radius: 10px;
  padding: 1rem 1.1rem;
  transition: all 0.25s ease;
}

.ai-stat-card:hover {
  border-color: rgba(0, 229, 255, 0.35);
  transform: translateY(-2px);
}

.ai-stat-label {
  color: var(--text-muted);
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.68rem;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.ai-stat-value {
  color: #ffffff;
  font-size: 1.5rem;
  font-weight: 800;
  margin: 0.35rem 0 0.15rem;
  font-family: 'Share Tech Mono', monospace;
}

.ai-stat-value.big {
  font-size: 1.65rem;
}

.ai-stat-sub {
  color: var(--text-muted);
  font-size: 0.72rem;
}

.ai-stat-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.85rem;
}

@media (max-width: 480px) {
  .ai-stat-grid-2 {
    grid-template-columns: 1fr;
  }
}

.ai-mover-row {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.ai-mover-sym {
  color: #ffffff;
  font-family: 'Share Tech Mono', monospace;
  font-weight: 800;
  font-size: 1rem;
}

.ai-mover-change {
  font-family: 'Share Tech Mono', monospace;
  font-weight: bold;
  font-size: 0.9rem;
}

.ai-mover-change.up {
  color: #10b981;
}

.ai-mover-change.down {
  color: #ef4444;
}

/* Section Headers */
.section-header-wrap {
  max-width: 1200px;
  margin: 3.5rem auto 1.75rem;
  padding: 0 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1.5rem;
  position: relative;
  z-index: 10;
}

.section-title-wrap {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex: 1;
}

.section-title {
  font-family: 'Share Tech Mono', monospace;
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 2.5px;
  color: #ffffff;
  text-transform: uppercase;
  margin: 0;
  white-space: nowrap;
}

.section-line {
  height: 1px;
  background: linear-gradient(90deg, rgba(0, 229, 255, 0.25), transparent);
  flex: 1;
}

.section-badge {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.65rem;
  font-weight: 800;
  color: var(--accent);
  border: 1px solid rgba(0, 229, 255, 0.35);
  padding: 0.25rem 0.65rem;
  border-radius: 4px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

/* Featured Section layout */
.featured-section {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
  display: grid;
  grid-template-columns: 1fr;
  grid-template-areas:
    "left"
    "header"
    "right";
  gap: 2rem;
  position: relative;
  z-index: 10;
}

.featured-section-header {
  grid-area: header;
  margin: 0;
  padding: 0;
  max-width: none;
}

.featured-section-left {
  grid-area: left;
}

.featured-section-right {
  grid-area: right;
}

@media (min-width: 769px) {
  .featured-section {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "header header"
      "left right";
  }
}

.featured-card {
  background: rgba(11, 21, 36, 0.5);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.featured-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0, 229, 255, 0.25), transparent);
}

.emblem-container {
  width: 100%;
  height: 380px;
  position: relative;
  overflow: hidden;
}

.site-emblem-frame {
  width: 100%;
  height: 100%;
  border: 0;
  background: transparent;
  display: block;
}

.featured-card-bordered {
  border: 1px solid rgba(0, 229, 255, 0.45);
  box-shadow: 0 0 0 1px rgba(0, 229, 255, 0.12), 0 0 28px rgba(0, 229, 255, 0.12);
}

.rizon-image-wrap {
  width: 100%;
  padding: 1.1rem 1.1rem 0;
  height: auto;
  position: relative;
  overflow: visible;
  background: transparent;
  box-sizing: border-box;
}

.rizon-image {
  display: block;
  width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: 10px;
  transition: transform 0.5s ease;
}

.featured-card:hover .rizon-image {
  transform: scale(1.03);
}

.rizon-site-link {
  position: absolute;
  right: 2.1rem;
  bottom: -18px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #0a4d5c);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 14px rgba(0, 229, 255, 0.4);
  border: 2px solid #0b1524;
  color: #060a12;
  text-decoration: none;
  z-index: 5;
}

.rizon-site-link svg {
  width: 18px;
  height: 18px;
}

.rizon-content {
  padding: 1.9rem 1.75rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  flex: 1;
  justify-content: space-between;
}

.rizon-title {
  font-family: 'Outfit', sans-serif;
  font-size: 1.6rem;
  font-weight: 900;
  color: #ffffff;
  margin: 0 0 0.5rem 0;
}

.rizon-category-wrap {
  margin-bottom: 0.75rem;
}

.rizon-category {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--accent);
  letter-spacing: 2px;
  text-transform: uppercase;
  border-top: 1px solid rgba(0, 229, 255, 0.2);
  border-bottom: 1px solid rgba(0, 229, 255, 0.2);
  padding: 0.25rem 1rem;
  display: inline-block;
}

.rizon-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin: 0 0 1.5rem 0;
  max-width: 380px;
}

.btn-review-read {
  width: 100%;
  background: var(--accent);
  color: #060a12;
  padding: 0.85rem;
  border-radius: 6px;
  font-family: 'Outfit', sans-serif;
  font-size: 0.85rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-decoration: none;
  box-shadow: 0 4px 12px rgba(0, 229, 255, 0.15);
  transition: all 0.2s ease;
  display: block;
  box-sizing: border-box;
}

.btn-review-read:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 20px rgba(0, 229, 255, 0.4);
  transform: translateY(-1px);
}

/* Single Post Layout styling */
.single-post-container {
  max-width: 850px;
  margin: 2.5rem auto 5rem;
  padding: 0 2rem;
  color: #e2e8f0;
  font-family: 'Inter', sans-serif;
}

.single-post-header {
  margin-bottom: 2rem;
  text-align: left;
}

.single-post-meta-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
  position: relative;
}

.single-post-meta-labels .post-category-tag {
  position: relative !important;
  bottom: auto !important;
  left: auto !important;
  display: inline-flex !important;
  align-items: center;
  margin: 0;
  z-index: 1;
}

.single-post-title {
  font-size: 2.5rem;
  font-weight: 800;
  color: #ffffff;
  line-height: 1.2;
  letter-spacing: -0.5px;
  margin-bottom: 1rem;
  font-family: 'Outfit', sans-serif;
  text-shadow: 0 0 40px rgba(0, 229, 255, 0.1);
}

.single-post-meta {
  font-size: 0.9rem;
