body.script:
//
(function(){
  var MIN_DISPLAY_MS = 900;
  var MAX_WAIT_MS = 6000;
  var startTime = Date.now();
  var loader = document.getElementById('ca-page-loader');
  var hidden = false;
  function hideLoader(){
    if (hidden || !loader) return;
    hidden = true;
    var elapsed = Date.now() - startTime;
    var remaining = MIN_DISPLAY_MS - elapsed;
    setTimeout(function(){
      loader.classList.add('ca-loader-hidden');
      setTimeout(function(){
        if (loader && loader.parentNode) { loader.parentNode.removeChild(loader); }
      }, 600);
    }, remaining > 0 ? remaining : 0);
  }
  if (document.readyState === 'complete') {
    hideLoader();
  } else {
    window.addEventListener('load', hideLoader);
  }
  setTimeout(hideLoader, MAX_WAIT_MS);
})();
//

//
(function() {
  var caTickIds = {
    btc: 'bitcoin',
    eth: 'ethereum',
    sol: 'solana',
    kas: 'kaspa',
    bnb: 'binancecoin',
    xrp: 'ripple'
  };

  function caTickFormatPrice(key, value) {
    if (value >= 100) {
      return '$' + value.toLocaleString('en-US', {maximumFractionDigits: 0});
    } else if (value >= 1) {
      return '$' + value.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
    } else {
      return '$' + value.toLocaleString('en-US', {minimumFractionDigits: 4, maximumFractionDigits: 4});
    }
  }

  function caTickUpdate(key, price, change, logoUrl) {
    var topLogoEl = document.getElementById('ca-tick-' + key + '-logo');
    var topPriceEl = document.getElementById('ca-tick-' + key + '-price');
    var topChangeEl = document.getElementById('ca-tick-' + key + '-change');

    var formattedPrice = caTickFormatPrice(key, price);
    var isUp = change >= 0;
    var arrow = isUp ? '\u25B2 ' : '\u25BC ';
    var sign = isUp ? '+' : '';
    var formattedChange = arrow + sign + change.toFixed(2) + '%';

    var tickerClass = 'ticker-change ' + (isUp ? 'up' : 'down');

    if (topLogoEl && logoUrl) topLogoEl.src = logoUrl;
    if (topPriceEl) topPriceEl.textContent = formattedPrice;
    if (topChangeEl) {
      topChangeEl.textContent = formattedChange;
      topChangeEl.className = tickerClass;
    }
  }

  function caTickFetch() {
    var ids = 'bitcoin,ethereum,solana,kaspa,binancecoin,ripple';
    var url = 'https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd\x26ids=' + ids + '\x26price_change_percentage=24h';
    var xhr = new XMLHttpRequest();
    xhr.open('GET', url, true);
    xhr.onreadystatechange = function() {
      if (xhr.readyState === 4 && xhr.status === 200) {
        try {
          var data = JSON.parse(xhr.responseText);
          for (var i = 0; i < data.length; i++) {
            var coin = data[i];
            for (var k in caTickIds) {
              if (caTickIds[k] === coin.id) {
                caTickUpdate(k, coin.current_price, coin.price_change_percentage_24h || 0, coin.image);
              }
            }
          }
        } catch (e) {}
      }
    };
    xhr.send();
  }

  caTickFetch();
  setInterval(caTickFetch, 60000);
})();
